package com.openggf.game.soniccd.level;
import com.openggf.game.soniccd.objects.*;
import org.junit.jupiter.api.Test;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
/** Tests FIRST; Java UNRUN. Data-only original C/D catalogue extension, no current/art/World grant. */
class TestCdR13BossWorldMappings {
    @Test void bossMetadataRetainsExactAggregateAndRejectsForeignPair()throws Exception {var f=TestCdR13FutureAssets.retail();for(var a:f.all()){var boss=CdR13BossAssets.bind(a);assertTrue(boss.ownsAssets(a));assertFalse(boss.ownsAssets(a==f.good()?f.bad():f.good()));assertFalse(boss.ownsAssets(null));assertEquals(35,boss.ranges().size());}}
    @Test void fourthCatalogueAddsOnlyTenActualBossRootsAndTwentyFourFrames()throws Exception {for(var a:TestCdR13FutureAssets.retail().all()){var o=CdR13ObjectAssets.fromAssets(a);var r=CdR13ReusedObjectAssets.fromAssets(a,o);var boss=CdR13BossAssets.bind(a);var before=CdObjectMappings.fromAct3FutureAssets(a,o,r);var after=CdObjectMappings.fromAct3FutureAssets(a,o,r,boss);assertEquals(17,count(before,"tables"));assertEquals(27,count(after,"tables"));assertEquals(8,count(before,"staticPieces"));assertEquals(8,count(after,"staticPieces"));int frames=0;for(var v:CdR13BossAssets.Visual.values()){var visual=boss.visual(v);var raw=boss.view(v.mappingTable());int address=boss.range(v.mappingTable()).nativeAddress();var declared=CdObjectMappings.declaredSourceViews(List.of(new CdObjectMappings.DeclaredTable(address,raw,0,v.frameCount())),List.of());for(int frame=0;frame<v.frameCount();frame++){assertEquals(declared.resolve(address,false,frame),after.resolve(address,false,frame));frames++;}assertThrows(UnsupportedOperationException.class,()->before.resolve(address,false,0));assertThrows(UnsupportedOperationException.class,()->after.resolve(address,false,v.frameCount()));assertSame(visual,boss.visual(v));}assertEquals(24,frames);}}
    @Test void actualParentOwnedForearmMappingsRemainTwoDistinctRoots()throws Exception {for(var a:TestCdR13FutureAssets.retail().all()){var b=CdR13BossAssets.bind(a);var first=b.range(CdR13BossAssets.Visual.FOREARM1.mappingTable());var second=b.range(CdR13BossAssets.Visual.FOREARM2.mappingTable());assertNotEquals(first.nativeAddress(),second.nativeAddress());assertEquals(3,b.visual(CdR13BossAssets.Visual.FOREARM1).mappingFrames().size());assertEquals(3,b.visual(CdR13BossAssets.Visual.FOREARM2).mappingFrames().size());assertEquals(2,b.mappingStores().stream().filter(s->s.producer()==CdR13BossAssets.Part.EGGMAN&&s.visual().name().startsWith("FOREARM")).count());}}
    @Test void foreignAuthenticatedBossAndNullDoNotExtendCorrectCatalogue()throws Exception {var f=TestCdR13FutureAssets.retail();var o=CdR13ObjectAssets.fromAssets(f.good());var r=CdR13ReusedObjectAssets.fromAssets(f.good(),o);assertThrows(IllegalArgumentException.class,()->CdObjectMappings.fromAct3FutureAssets(f.good(),o,r,CdR13BossAssets.bind(f.bad())));assertThrows(NullPointerException.class,()->CdObjectMappings.fromAct3FutureAssets(f.good(),o,r,null));}
    private static int count(CdObjectMappings value,String name)throws Exception{var f=CdObjectMappings.class.getDeclaredField(name);f.setAccessible(true);return ((Map<?,?>)f.get(value)).size();}
}
